INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 42, 'theory', 'Quiz: Multiple Inheritance and MRO');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 42, 0, 'What is the MRO of D(B, C) if B and C inherit from A?', '["D, A, B, C, object", "D, B, A, C, object", "D, C, B, A, object", "D, B, C, A, object"]', 3, 'C3: a class comes before its parents, the order of the bases is preserved, and the common ancestor A comes after both descendants.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 42, 1, 'What does super() actually do?', '["Always calls the immediate parent", "Calls the next class in the MRO of the object''s own type", "Calls object", "Creates a copy of the object"]', 1, 'That is why inside B, for an object of D(B, C), super() passes control to C, not A.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 42, 2, 'What happens with class C(A, B) if B inherits from A?', '["TypeError: cannot build a consistent MRO", "The class is created, A runs twice", "Python reorders the bases", "The class is created, but without A''s methods"]', 0, 'The C3 requirements are incompatible: A cannot be placed before its descendant B.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 42, 3, 'Where is it customary to put mixins in the list of bases?', '["To the right of the main base", "To the left of the main base", "The order doesn''t matter", "Mixins can''t be used with super()"]', 1, 'On the left, so that their methods come earlier in the MRO and can wrap the main class''s method through super().');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 42, 4, 'Why does a mixin''s __init__ accept **kwargs and call super().__init__(**kwargs)?', '["For speed", "So the init chain passes through the whole MRO and extra parameters reach the right class", "To forbid arguments", "To call object twice"]', 1, 'Cooperative inheritance: each class takes its own and passes the rest on.');
